def isPalindrome(n):
    if n < 0:
        return 0
    original = n
    reverse = 0
    while n > 0:
        reverse = reverse * 10 + n % 10
        n = n // 10
    return 1 if reverse == original else 0

num = int(input())
if isPalindrome(num):
    print("Palindrome")
else:
    print("Not Palindrome")
